action.code:
if (!end_node) {
    return {};
}
distance_ = 0.0f;
std::vector<RouteModel::Node> path;
RouteModel::Node* current = end_node;
while (current) {
    path.push_back(*current);
    if (current->parent) {
        distance_ += current->distance(*(current->parent));
    }
    current = current->parent;
}
std::reverse(path.begin(), path.end());
m_model_.path = path;
return path;

